import{_ as s,o as a,c as e,a0 as p}from"./chunks/framework.jwovEGr5.js";const u=JSON.parse('{"title":"End-to-End Analysis Pipeline","description":"","frontmatter":{},"headers":[],"relativePath":"frensense-paper/09_PIPELINE.md","filePath":"frensense-paper/09_PIPELINE.md"}'),l={name:"frensense-paper/09_PIPELINE.md"};function i(t,n,r,c,o,d){return a(),e("div",null,[...n[0]||(n[0]=[p(`<h1 id="end-to-end-analysis-pipeline" tabindex="-1">End-to-End Analysis Pipeline <a class="header-anchor" href="#end-to-end-analysis-pipeline" aria-label="Permalink to &quot;End-to-End Analysis Pipeline&quot;">​</a></h1><p>This document traces a single file through the entire Frensense analysis pipeline from disk to finding.</p><hr><h2 id="pipeline-diagram" tabindex="-1">Pipeline Diagram <a class="header-anchor" href="#pipeline-diagram" aria-label="Permalink to &quot;Pipeline Diagram&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> ─────────────────────────────────────────────────────────────────────</span></span>
<span class="line"><span> INPUT: source directory (e.g., src/)</span></span>
<span class="line"><span> ─────────────────────────────────────────────────────────────────────</span></span>
<span class="line"><span>         │</span></span>
<span class="line"><span>         ▼</span></span>
<span class="line"><span> ┌─────────────────┐</span></span>
<span class="line"><span> │  File Walker    │  walkdir: recursive, depth-first</span></span>
<span class="line"><span> │  (auditor/)     │  rayon: parallel across files</span></span>
<span class="line"><span> └────────┬────────┘</span></span>
<span class="line"><span>          │ exclude: node_modules/, target/, *.test.*, *.min.js, &gt;1 MB</span></span>
<span class="line"><span>          │</span></span>
<span class="line"><span>         ▼</span></span>
<span class="line"><span> ┌─────────────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span> │  analyze_file(source, language, path, file_id)                  │</span></span>
<span class="line"><span> │  frensense-engine/src/lib.rs                                    │</span></span>
<span class="line"><span> │                                                                  │</span></span>
<span class="line"><span> │  1. tree-sitter parse → CST (concrete syntax tree)             │</span></span>
<span class="line"><span> │  2. ImportMap::build_from_tree() → local alias → package map   │</span></span>
<span class="line"><span> │  3. HandlerRegistry::build() → route registration map          │</span></span>
<span class="line"><span> │  4. fingerprint::extract_fingerprints()                         │</span></span>
<span class="line"><span> │     ├── Walk all function/method/arrow nodes                    │</span></span>
<span class="line"><span> │     ├── extract ngram_hashes (w=3,5,8 rolling hash)            │</span></span>
<span class="line"><span> │     ├── extract structural_markers (if/loop/try counts)        │</span></span>
<span class="line"><span> │     ├── extract semantic_markers (dangerous API hashes)        │</span></span>
<span class="line"><span> │     ├── extract api_calls, api_call_segments                   │</span></span>
<span class="line"><span> │     ├── extract motif_hashes (semantic source/sink groups)     │</span></span>
<span class="line"><span> │     ├── extract control_flow_hashes (CFG path enumeration)     │</span></span>
<span class="line"><span> │     ├── extract data_flow_path_hashes (flow_fingerprint.rs)    │</span></span>
<span class="line"><span> │     └── extract tainted_api_calls (param→api-call links)       │</span></span>
<span class="line"><span> │  5. SymbolRegistry::extract_from_tree() → symbol table        │</span></span>
<span class="line"><span> │  6. SemanticExtractor::extract() → Vec&lt;SemanticOp&gt;            │</span></span>
<span class="line"><span> │     (normalized IR: Binding, Assignment, Call, Return)          │</span></span>
<span class="line"><span> │  7. SemanticGraph construction (full-analysis feature)         │</span></span>
<span class="line"><span> │  8. temporal_events extraction                                  │</span></span>
<span class="line"><span> └────────────────────────────┬────────────────────────────────────┘</span></span>
<span class="line"><span>                               │</span></span>
<span class="line"><span>                               ▼ AnalysisResult per file</span></span>
<span class="line"><span> ┌─────────────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span> │  analyze_project() - cross-file pass                           │</span></span>
<span class="line"><span> │  frensense-engine/src/lib.rs                                    │</span></span>
<span class="line"><span> │                                                                  │</span></span>
<span class="line"><span> │  1. Merge all SemanticGraphs → global_graph                    │</span></span>
<span class="line"><span> │  2. cross_file::build_resolver(symbols, graph)                 │</span></span>
<span class="line"><span> │  3. Seed HTTP handlers as TaintOrigin::UserInput sources        │</span></span>
<span class="line"><span> │  4. resolver.propagate_taint(None) - BFS over Calls edges       │</span></span>
<span class="line"><span> │  5. For DbQuery/ShellExecutor functions:                        │</span></span>
<span class="line"><span> │     resolver.resolve_taint(fn_name, file, depth=10)            │</span></span>
<span class="line"><span> │     → if tainted: update fingerprint.tainted_api_calls         │</span></span>
<span class="line"><span> │  6. Return-value taint propagation:                             │</span></span>
<span class="line"><span> │     let result = dbQuery() → mark &#39;result&#39; as tainted binding  │</span></span>
<span class="line"><span> │  7. Second pass: update is_registered_handler via project       │</span></span>
<span class="line"><span> │     route registry (cross-file route registrations)            │</span></span>
<span class="line"><span> └────────────────────────────┬────────────────────────────────────┘</span></span>
<span class="line"><span>                               │</span></span>
<span class="line"><span>                               ▼ ProjectAnalysis</span></span>
<span class="line"><span> ┌─────────────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span> │  Engine.scan() - per function, per file                        │</span></span>
<span class="line"><span> │  src/engine/auditor/                                            │</span></span>
<span class="line"><span> │                                                                  │</span></span>
<span class="line"><span> │  For each file, for each function fingerprint:                  │</span></span>
<span class="line"><span> │                                                                  │</span></span>
<span class="line"><span> │  A. FunctionRole classification (zero cost, fingerprint-only)   │</span></span>
<span class="line"><span> │     → HttpHandler / DbQuery / ShellExecutor / DataTransformer   │</span></span>
<span class="line"><span> │                                                                  │</span></span>
<span class="line"><span> │  B. SemanticFilter pre-check (O(1) per pattern)                 │</span></span>
<span class="line"><span> │     → skip pattern if contains_call_to not satisfied           │</span></span>
<span class="line"><span> │     → skip pattern if must_not_contain_import violated         │</span></span>
<span class="line"><span> │     → skip if function_name_regex doesn&#39;t match               │</span></span>
<span class="line"><span> │                                                                  │</span></span>
<span class="line"><span> │  C. LSH Candidate Retrieval                                    │</span></span>
<span class="line"><span> │     1. minhash_signature(ngram_hashes, 120 hashes)             │</span></span>
<span class="line"><span> │     2. Query 40 LSH bands → union of matching pattern IDs      │</span></span>
<span class="line"><span> │     3. Also query lsh_index_api (API call hashes)              │</span></span>
<span class="line"><span> │     4. Also query flow_index (exact flow path hashes)          │</span></span>
<span class="line"><span> │     → candidate_set: typically 0-20 patterns                   │</span></span>
<span class="line"><span> │                                                                  │</span></span>
<span class="line"><span> │  D. 15-Dimensional Scoring (per candidate pattern)             │</span></span>
<span class="line"><span> │     1. Compute RawDimensions:                                   │</span></span>
<span class="line"><span> │        ngram_sim, ast_sim, signature_sim, param_type_sim,       │</span></span>
<span class="line"><span> │        type_usage_sim, semantic_sim, cf_sim, api_sim,           │</span></span>
<span class="line"><span> │        tainted_api_sim, motif_sim, flow_sim, config_sim,        │</span></span>
<span class="line"><span> │        cf_order_sim, arg_type_sim, literal_concat_sim           │</span></span>
<span class="line"><span> │     2. identity_gate = max(api_sim, semantic_sim, ast_sim,      │</span></span>
<span class="line"><span> │                             motif_sim, flow_sim)                │</span></span>
<span class="line"><span> │        gate = min(identity_gate * 2.5 + 0.1, 1.0)             │</span></span>
<span class="line"><span> │     3. vuln_score = Σ (dim_i * weight_i), gated by gate        │</span></span>
<span class="line"><span> │     4. Contrastive: score vs. negative fingerprints            │</span></span>
<span class="line"><span> │        final = pos_score - neg_penalty_weight * neg_score       │</span></span>
<span class="line"><span> │     5. Profile boost (rare n-grams in this codebase)           │</span></span>
<span class="line"><span> │     6. Cross-lingual penalty (if pattern lang ≠ file lang)     │</span></span>
<span class="line"><span> │     7. Sigmoid calibration: σ(A * score + B)                   │</span></span>
<span class="line"><span> │                                                                  │</span></span>
<span class="line"><span> │  E. Threshold gate: discard if score &lt; threshold (default 0.65) │</span></span>
<span class="line"><span> │                                                                  │</span></span>
<span class="line"><span> │  F. Taint Verification (DataFlowEngine)                        │</span></span>
<span class="line"><span> │     → Walk function AST with TaintRegistry                     │</span></span>
<span class="line"><span> │     → tag = &quot;taint-verified&quot; if source→sink path confirmed     │</span></span>
<span class="line"><span> │     → score boost ×1.2 if verified; penalty ×0.6 if not        │</span></span>
<span class="line"><span> │                                                                  │</span></span>
<span class="line"><span> │  G. Advisory emission                                           │</span></span>
<span class="line"><span> │     → Interpolate {{ source }}, {{ sink }} in observation text  │</span></span>
<span class="line"><span> │     → Attach MatchEvidence (per-dimension breakdown)           │</span></span>
<span class="line"><span> │     → Attach CWE/CVSS/OWASP from pattern metadata             │</span></span>
<span class="line"><span> │                                                                  │</span></span>
<span class="line"><span> │  H. Rule-based checks (parallel to corpus pipeline)            │</span></span>
<span class="line"><span> │     → FrensenseRule.check() for all registered rules           │</span></span>
<span class="line"><span> │     → Temporal property checks (event sequence verification)   │</span></span>
<span class="line"><span> └────────────────────────────┬────────────────────────────────────┘</span></span>
<span class="line"><span>                               │</span></span>
<span class="line"><span>                               ▼ raw Advisory list</span></span>
<span class="line"><span> ┌─────────────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span> │  Post-Processing                                                │</span></span>
<span class="line"><span> │  src/engine/composition.rs + findings/                         │</span></span>
<span class="line"><span> │                                                                  │</span></span>
<span class="line"><span> │  1. apply_composition() - AND-gate multi-layer confidence:      │</span></span>
<span class="line"><span> │     ├── L1∧L2 (corpus + taint): full confidence                │</span></span>
<span class="line"><span> │     ├── L1 only: ×0.6 penalty                                  │</span></span>
<span class="line"><span> │     ├── L3: validator suppression (ratio&gt;0.85 + name): ×0.3   │</span></span>
<span class="line"><span> │     └── L4: near-duplicate boost ×1.1, cap at +0.30           │</span></span>
<span class="line"><span> │                                                                  │</span></span>
<span class="line"><span> │  2. Deduplication: (rule_id, file, line) → one advisory        │</span></span>
<span class="line"><span> │                                                                  │</span></span>
<span class="line"><span> │  3. Baseline suppression:                                       │</span></span>
<span class="line"><span> │     → Load .frensense-suppress.yml                              │</span></span>
<span class="line"><span> │     → Remove advisories matching suppression entries           │</span></span>
<span class="line"><span> │                                                                  │</span></span>
<span class="line"><span> │  4. Threshold filtering:                                        │</span></span>
<span class="line"><span> │     → Apply --severity flag                                    │</span></span>
<span class="line"><span> │     → Apply --min-confidence flag                              │</span></span>
<span class="line"><span> │     → Apply --strict flag (Critical only)                      │</span></span>
<span class="line"><span> └────────────────────────────┬────────────────────────────────────┘</span></span>
<span class="line"><span>                               │</span></span>
<span class="line"><span>                               ▼ filtered Advisory list</span></span>
<span class="line"><span> ┌─────────────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span> │  Reporter                                                       │</span></span>
<span class="line"><span> │  src/reporter.rs                                                │</span></span>
<span class="line"><span> │                                                                  │</span></span>
<span class="line"><span> │  → terminal: colored ANSI output with code snippet context      │</span></span>
<span class="line"><span> │  → --json: Advisory structs serialized to JSON array           │</span></span>
<span class="line"><span> │  → --sarif: SARIF 2.1.0 with CodeFlow + MatchEvidence          │</span></span>
<span class="line"><span> │  → --baseline: emit baseline.json for future suppression        │</span></span>
<span class="line"><span> └─────────────────────────────────────────────────────────────────┘</span></span>
<span class="line"><span> OUTPUT: findings / exit code 0 (clean) or 1 (findings)</span></span></code></pre></div><hr><h2 id="parallelism-model" tabindex="-1">Parallelism Model <a class="header-anchor" href="#parallelism-model" aria-label="Permalink to &quot;Parallelism Model&quot;">​</a></h2><p>Frensense uses <code>rayon</code> for data-parallel work at three levels:</p><table tabindex="0"><thead><tr><th>Level</th><th>What Is Parallelized</th><th>Granularity</th></tr></thead><tbody><tr><td>File level</td><td><code>analyze_file()</code> per file</td><td>Per CPU core</td></tr><tr><td>Corpus matching</td><td><code>score_against()</code> per pattern candidate</td><td>Per function</td></tr><tr><td>Rule dispatch</td><td><code>rule.check()</code> per rule</td><td>Per node (small)</td></tr></tbody></table><p>The <code>TaintCache</code> uses <code>RefCell</code> (not <code>Mutex</code>) because it is only accessed from one thread at a time per file. Cross-file state (the global <code>SemanticGraph</code>) is built sequentially after parallel file analysis completes.</p><hr><h2 id="data-flow-invariants" tabindex="-1">Data Flow Invariants <a class="header-anchor" href="#data-flow-invariants" aria-label="Permalink to &quot;Data Flow Invariants&quot;">​</a></h2><p>These invariants hold at each stage:</p><table tabindex="0"><thead><tr><th>Stage</th><th>Invariant</th></tr></thead><tbody><tr><td>After <code>analyze_file</code></td><td>Every function has a complete <code>FunctionFingerprint</code>. No cross-file state is consulted.</td></tr><tr><td>After <code>analyze_project</code></td><td><code>tainted_api_calls</code> may be updated for sink functions reachable from HTTP handlers. <code>is_registered_handler</code> is accurate project-wide.</td></tr><tr><td>After corpus scan</td><td>Every emitted <code>Advisory</code> has <code>confidence &gt; threshold</code> and a non-empty <code>match_evidence</code>.</td></tr><tr><td>After composition</td><td><code>confidence</code> may be lower than after scoring but never higher than <code>1.0</code>.</td></tr><tr><td>After dedup</td><td>At most one <code>Advisory</code> per <code>(rule_id, file_path, line)</code> tuple.</td></tr></tbody></table><hr><h2 id="failure-modes" tabindex="-1">Failure Modes <a class="header-anchor" href="#failure-modes" aria-label="Permalink to &quot;Failure Modes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Failure</th><th>Behavior</th></tr></thead><tbody><tr><td>Parse error (malformed source)</td><td>Skip file, log warning, continue</td></tr><tr><td>Unsupported language</td><td>Skip file silently</td></tr><tr><td>Bundle load failure</td><td>Fatal error, exit 1</td></tr><tr><td>Bundle checksum mismatch</td><td>Fatal error, exit 1 (corrupted bundle)</td></tr><tr><td>Individual rule panic</td><td>Catch unwind, skip rule for this file, log error</td></tr><tr><td>Taint walk timeout</td><td>Abort taint walk, emit advisory without &quot;taint-verified&quot; tag</td></tr></tbody></table>`,17)])])}const f=s(l,[["render",i]]);export{u as __pageData,f as default};
